package net.civeira.phylax.feature.observe.observedissuealias.domain.gateway;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueReference;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceReference;

class ObservedIssueAliasFilterUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_observed_issue_alias_filter_builder() {
    ObservedIssueAliasFilter filter = ObservedIssueAliasFilter.builder().build();
    Assertions.assertFalse(filter.getUid().isPresent(),
        "Uid must be empty if filter is build without it");
    filter.setUid("one");
    Assertions.assertEquals("one", filter.getUid().get(), "Uid must be the same as the assigned");
    Assertions.assertTrue(filter.getUids().isEmpty(),
        "Uid must be empty if filter is build without it");
    filter.setUids(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getUids(),
        "Uids must be the same as the assigned");
    Assertions.assertFalse(filter.getSearch().isPresent(),
        "Search must be empty if filter is build without it");
    filter.setSearch("lookup");
    Assertions.assertEquals("lookup", filter.getSearch().get(),
        "Search must be the same as the assigned");
    Assertions.assertFalse(filter.getIssue().isPresent(),
        "Issue must be empty if filter is build without it");
    filter.setIssue(ObservedIssueReference.of("$ref"));
    Assertions.assertEquals(ObservedIssueReference.of("$ref"), filter.getIssue().get(),
        "Issue must be the same as the assigned");
    Assertions.assertFalse(filter.getFingerprint().isPresent(),
        "Fingerprint must be empty if filter is build without it");
    filter.setFingerprint("one");
    Assertions.assertEquals("one", filter.getFingerprint().get(),
        "Fingerprint must be the same as the assigned");
    Assertions.assertFalse(filter.getOrigin().isPresent(),
        "Origin must be empty if filter is build without it");
    filter.setOrigin(ObservedSourceReference.of("$ref"));
    Assertions.assertEquals(ObservedSourceReference.of("$ref"), filter.getOrigin().get(),
        "Origin must be the same as the assigned");
    Assertions.assertTrue(filter.getOrigins().isEmpty(),
        "Origins must be empty if filter is build without it");
    filter.setOrigins(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getOrigins(),
        "Origins must be the same as the assigned");
  }

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test the filter of a unique index")
  void test_observed_issue_alias_filter_by_origin_and_fingerprint() {
    ObservedIssueAliasFilter filter =
        ObservedIssueAliasFilter.byOriginAndFingerprint(ObservedSourceReference.of("$ref"), "one");
    Assertions.assertEquals(ObservedSourceReference.of("$ref"), filter.getOrigin().orElse(null),
        "Origin must be the one of the unique index");
    Assertions.assertEquals("one", filter.getFingerprint().orElse(null),
        "Fingerprint must be the one of the unique index");
  }
}
